#!/usr/bin/env python3
"""Build and verify both EvalBot diagrams.

    python3 architecture/build_diagram.py

Variants
--------
* ``evalbot-architecture``         the simple, logo-driven infographic — generated by
                                   ``make_simple.py`` from the brand logos in ``logos/``
* ``evalbot-architecture-detail``  the hand-authored service-by-service map

For each variant the SVG is the single source of truth: the HTML page inlines it and the
PNG is rasterised from it (simple 2.4x, detail 2x), cross-checked against an independent
inkscape export.

Because a clipped, overflowing or colliding label is invisible to a diff, every ``<text>``
element is measured with the real system fonts (PIL + fc-match) against the box that
contains it, and each logo badge's pixel colour is sampled from the finished PNG. The
build fails loudly instead of shipping a broken image.
"""
from __future__ import annotations

import re
import subprocess
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

import cairosvg
from PIL import Image, ImageFont

import make_simple

