errors: list[str] = []
notes: list[str] = []


# --------------------------------------------------------------------------- fonts
def font_file(spec: str) -> str:
    return subprocess.run(
        ["fc-match", "-f", "%{file}", spec], capture_output=True, text=True, check=True
    ).stdout.strip()


_FONTS: dict[tuple[str, bool], ImageFont.FreeTypeFont] = {}


def measure(text: str, family: str, size: float, weight: int) -> float:
    fam = family.lower()
    if "mono" in fam:
        key = ("mono", False)
    elif "serif" in fam or "c059" in fam or "newsreader" in fam or "georgia" in fam:
        key = ("serif", False)
    else:
        key = ("sans", weight >= 600)
    if key not in _FONTS:
        spec = {
            ("mono", False): "DejaVu Sans Mono",
            ("serif", False): "C059",
            ("sans", False): "Inter",
            ("sans", True): "Inter SemiBold",
        }[key]
        _FONTS[key] = ImageFont.truetype(font_file(spec), 100)
    # measured at 100 px and scaled: PIL's small float sizes are not portable
    return _FONTS[key].getlength(text) * size / 100.0


# ------------------------------------------------------------------------ inherits
DEFAULTS = {
    "font-family": "Inter, 'DejaVu Sans', sans-serif",
    "font-size": "12",
    "font-weight": "400",
    "letter-spacing": "0",
    "text-anchor": "start",
}


def resolved(el: ET.Element, parent_map: dict, prop: str) -> str:
    node: ET.Element | None = el
    while node is not None:
        if node.get(prop):
            return node.get(prop)
        node = parent_map.get(node)
    return DEFAULTS[prop]


def num(value: str | None, default: float = 0.0) -> float:
    try:
        return float(re.sub(r"[^0-9.\-]", "", value or ""))
    except (TypeError, ValueError):
        return default


# ---------------------------------------------------------------------- svg checks
def check_svg(variant: dict, path: Path) -> None:
    raw = path.read_text(encoding="utf-8")
    root = ET.parse(path).getroot()
    parent_map = {child: parent for parent in root.iter() for child in parent}
    stem = variant["stem"]

    for bad in ('href="http', "href='http", "url(http", "<script", "@import"):
        if bad in raw:
            errors.append(f"[{stem}] external reference or script: {bad!r}")
    for attr in ("width", "height", "viewBox"):
        if not root.get(attr):
            errors.append(f"[{stem}] root svg missing {attr}")

    text = "".join(t.text or "" for t in root.iter(f"{NS}text"))
    for label in variant["required"]:
        if label not in text:
            errors.append(f"[{stem}] missing required label: {label!r}")
    for label in variant["forbidden"]:
        if label in text:
            errors.append(f"[{stem}] forbidden detail label in the simple view: {label!r}")

    # boxes: layer bands/cards (data-bounds) and the small event chips
    boxes = []
    for rect in root.iter(f"{NS}rect"):
        is_chip = rect.get("stroke", "").lower() in ("#d8d3c7", "#a9cfc9")
        if rect.get("data-bounds") != "1" and not is_chip:
            continue
        x, y = num(rect.get("x")), num(rect.get("y"))
        w, h = num(rect.get("width")), num(rect.get("height"))
        if not w or not h:
            continue
        boxes.append((x, y, x + w, y + h))

    spans: list[tuple[float, float, float, float, str]] = []
    texts = checked = skipped = 0
    for el in root.iter(f"{NS}text"):
        label = (el.text or "").strip()
        if not label:
            continue
        texts += 1
        anchor = resolved(el, parent_map, "text-anchor")

        node, transformed = el, False
        while node is not None:
            if node.get("transform"):
                transformed = True
                break
            node = parent_map.get(node)
        if transformed:  # rotated/transformed labels are checked by eye only
            skipped += 1
            continue

        size = num(resolved(el, parent_map, "font-size"), 12)
        weight = num(resolved(el, parent_map, "font-weight"), 400)
        spacing = num(resolved(el, parent_map, "letter-spacing"), 0)
        family = resolved(el, parent_map, "font-family")
        x, y = num(el.get("x")), num(el.get("y"))
        width = measure(label, family, size, int(weight)) + spacing * len(label)
        if anchor == "middle":
            x0, x1 = x - width / 2, x + width / 2
        elif anchor == "end":
            x0, x1 = x - width, x
        else:
            x0, x1 = x, x + width

        px, py = x, y - 0.3 * size
        holder = [b for b in boxes if b[0] <= px <= b[2] and b[1] <= py <= b[3]]
        if not holder:
            if x0 < 4 or x1 > num(root.get("width"), 1680) - 4:
                errors.append(f"[{stem}] text outside the canvas: {label[:48]!r} "
                              f"[{x0:.0f}..{x1:.0f}]")
            continue
        holder.sort(key=lambda b: (b[2] - b[0]) * (b[3] - b[1]))
        left, top, right, bottom = holder[0]
        pad = 5
        if x1 > right - pad or x0 < left + pad:
            errors.append(f"[{stem}] text overflow: {label[:52]!r} spans {x0:.0f}..{x1:.0f} "
                          f"({width:.0f}px) but its box is {left:.0f}..{right:.0f}")
        if y + 0.22 * size > bottom - 2:
            errors.append(f"[{stem}] text too low for its box: {label[:52]!r} "
                          f"baseline {y:.0f} vs bottom {bottom:.0f}")
        spans.append((x0, x1, y, size, label))
        checked += 1

    for i in range(len(spans)):
        x0, x1, y, size, label = spans[i]
        for j in range(i + 1, len(spans)):
            a0, a1, b_y, b_size, other = spans[j]
            if abs(y - b_y) < 0.8 * max(size, b_size) and x0 < a1 - 1 and a0 < x1 - 1:
                errors.append(f"[{stem}] labels collide: {label[:30]!r} and {other[:30]!r} "
                              f"at y={y:.0f}")

    notes.append(f"[{stem}] text: {texts} elements, {checked} measured, {skipped} transformed")

    # logo badges, for the pixel check on the raster
    badges = []
    for circle in root.iter(f"{NS}circle"):
        fill = circle.get("fill", "").lower()
        r = num(circle.get("r"))
        if fill in PALETTE and r >= 15:
            badges.append((num(circle.get("cx")), num(circle.get("cy")), r, fill))
    if variant["stem"] in ("evalbot-architecture", "evalbot-architecture-dark") and len(badges) < 8:
        errors.append(f"[{stem}] expected >= 8 logo badges, found {len(badges)}")
    notes.append(f"[{stem}] logo badges: {len(badges)}")
    variant["_badges"] = badges


