def write_html(variant: dict, svg_path: Path) -> Path:
    svg = svg_path.read_text(encoding="utf-8")
    size_free = r'(<svg[^>]*?) width="\d+" height="\d+"'
    svg = re.sub(r"^<\?xml[^>]*\?>\s*", "", svg)
    light = re.sub(size_free, r"\1", svg, count=1)
    svg_block = f'<div class="only-light">{light}</div>'
    dark_path = HERE / f"{variant['stem']}-dark.svg"
    if dark_path.exists():
        dark = re.sub(size_free, r"\1", dark_path.read_text(encoding="utf-8"), count=1)
        svg_block += f'<div class="only-dark">{dark}</div>'
    chips = "".join(f'<span class="chip">{c}</span>' if "AIMSEC" not in c
                    else f'<span class="chip"><b>{c}</b></span>' for c in variant["chips"])
    cards_block = ""
    if variant["cards"]:
        cards_block = ('  <section class="cards">'
                       + "".join(f'<div class="card"><h3>{h}</h3><p>{b}</p></div>'
                                 for h, b in variant["cards"])
                       + "</section>")
    if variant["stem"] == "evalbot-architecture":
        other = ('Detail view: <a href="evalbot-architecture-detail.html">'
                 'evalbot-architecture-detail.png</a>')
    else:
        other = ('Simple view: <a href="evalbot-architecture.html">'
                 'evalbot-architecture.png</a>')
    out = HERE / f"{variant['stem']}.html"
    out.write_text(PAGE.format(title=variant["title"], lede=variant["lede"],
                               heading=variant["heading"], chips=chips, svg=svg_block,
                               cards_block=cards_block, stem=variant["stem"], other=other),
                   encoding="utf-8")
    return out


# -------------------------------------------------------------------------- raster
def rasterise(variant: dict, svg_path: Path) -> Path:
    stem, scale = variant["stem"], variant["scale"]
    png = HERE / f"{stem}.png"
    cairosvg.svg2png(url=str(svg_path), write_to=str(png), scale=scale)

    tmp = HERE / f".{stem}-inkscape.png"
    subprocess.run(["inkscape", str(svg_path), "-o", str(tmp), "-w",
                    str(int(num(ET.parse(svg_path).getroot().get("width"), 1440) * scale))],
                   check=True, capture_output=True)
    with Image.open(png) as a, Image.open(tmp) as b:
        if a.size != b.size:
            errors.append(f"[{stem}] rasterisers disagree: cairosvg {a.size} vs inkscape {b.size}")
    tmp.unlink(missing_ok=True)
    return png


def verify_png(variant: dict, png: Path) -> None:
    stem, scale = variant["stem"], variant["scale"]
    size = png.stat().st_size
    with Image.open(png) as img:
        w, h = img.size
        rgb = img.convert("RGB")
        extrema = rgb.getextrema()
        colours = rgb.getcolors(maxcolors=1 << 22)
        pixels = rgb.load()

    notes.append(f"[{stem}] png {w}x{h}, {size / 1024:.0f} kB, "
                 f"{len(colours or [])} distinct colours")
    if w < 3000 or h < 700:  # the simple view is one band: demand width, not height
        errors.append(f"[{stem}] png too small: {w}x{h} (need >= 3000 wide, >= 700 tall)")
    if not 80 * 1024 <= size <= 8 * 1024 * 1024:
        errors.append(f"[{stem}] png size out of range: {size / 1024:.0f} kB")
    for channel, (lo, hi) in zip("RGB", extrema):
        if hi - lo < 40:
            errors.append(f"[{stem}] png looks blank on {channel}: extrema {lo}..{hi}")
    if not colours or len(colours) < 100:
        errors.append(f"[{stem}] too few distinct colours to be a real diagram")

    # every logo badge must actually show its brand colour in the raster
    bad = 0
    for cx, cy, r, fill in variant.get("_badges", []):
        want = tuple(int(fill[i:i + 2], 16) for i in (1, 3, 5))
        px = pixels[int((cx + 0.6 * r) * scale), int((cy + 0.6 * r) * scale)]
        if max(abs(a - b) for a, b in zip(px, want)) > 26:
            bad += 1
            if bad <= 3:
                errors.append(f"[{stem}] badge at ({cx:.0f},{cy:.0f}) is {px}, expected {want}")
    if bad:
        errors.append(f"[{stem}] {bad} logo badge(s) did not render their brand colour")


# ----------------------------------------------------------------------------- main
def main() -> int:
    light_svg, dark_svg = make_simple.main()
    notes.append(f"[simple] regenerated {light_svg.name} + {dark_svg.name}")

    for variant in VARIANTS:
        svg_path = HERE / f"{variant['stem']}.svg"
        if not svg_path.exists():
            errors.append(f"missing {svg_path.name}")
            continue
        check_svg(variant, svg_path)
        if errors:
            break
        if variant.get("html", True):
            html = write_html(variant, svg_path)
            notes.append(f"[{variant['stem']}] wrote {html.name} "
                         f"({html.stat().st_size / 1024:.0f} kB)")
        png = rasterise(variant, svg_path)
        verify_png(variant, png)

    for note in notes:
        print(note)
    if errors:
        print("\nFAILED:", file=sys.stderr)
        for err in errors:
            print(f"  - {err}", file=sys.stderr)
        return 1
    print("\nok: both diagrams built, all checks passed")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
